INSERT INTO `Instrument` VALUES ('AK-0030','Akuntabilitas','Suasana Akademik Program Studi','-','-','S3','[{\"id\":\"q1\",\"text\":\"Apakah terdapat dokumen formal kebijakan suasana akademik yang mencakup: otonomi keilmuan, kebebasan akademik, dan kebebasan mimbar akademik?\",\"bobot\":0},{\"id\":\"q2\",\"text\":\"Apakah kegiatan tridharma di PT menjunjung tinggi integritas dan etika akademik?\",\"bobot\":0},{\"id\":\"q3\",\"text\":\"Apakah suasana akademik yang kondusif terwujud secara konsisten setiap bulan?\",\"bobot\":0},{\"id\":\"q4\",\"text\":\"Apakah terdapat kegiatan seminar, diskusi ilmiah, dan koloqium secara rutin dalam program doktor?\",\"bobot\":0}]'),('AK-0032','Akuntabilitas','Sistem Layanan Mahasiswa','-','-','S3','[{\"id\":\"q1\",\"text\":\"Apakah terdapat program penyiapan mahasiswa baru mencakup 4 aspek: penjelasan umum PT, integritas akademik, bebas kekerasan, dan adaptasi kehidupan kampus?\",\"bobot\":0},{\"id\":\"q2\",\"text\":\"Apakah terdapat layanan administrasi akademik yang memadai?\",\"bobot\":0},{\"id\":\"q3\",\"text\":\"Apakah terdapat layanan bimbingan konseling?\",\"bobot\":0},{\"id\":\"q4\",\"text\":\"Apakah terdapat layanan kesehatan?\",\"bobot\":0},{\"id\":\"q5\",\"text\":\"Apakah terdapat layanan keperluan dasar mahasiswa berkebutuhan khusus?\",\"bobot\":0},{\"id\":\"q6\",\"text\":\"Apakah dilakukan survey kepuasan atas layanan mahasiswa?\",\"bobot\":0}]'),('AK-030','Akuntabilitas','Suasana Akademik Program Studi','-','-','S2','[{\"id\":\"q1\",\"text\":\"Apakah terdapat dokumen formal kebijakan suasana akademik: otonomi keilmuan, kebebasan akademik, dan kebebasan mimbar akademik?\",\"bobot\":0},{\"id\":\"q2\",\"text\":\"Apakah kegiatan tridharma menjunjung tinggi integritas dan etika akademik?\",\"bobot\":0},{\"id\":\"q3\",\"text\":\"Apakah suasana akademik yang kondusif terwujud secara konsisten setiap bulan?\",\"bobot\":0},{\"id\":\"q4\",\"text\":\"Apakah terdapat kegiatan seminar, diskusi ilmiah, dan kolokium secara rutin dalam program magister?\",\"bobot\":0}]'),('AK-032','Akuntabilitas','Sistem Layanan Mahasiswa','-','-','S2','[{\"id\":\"q1\",\"text\":\"Apakah terdapat program penyiapan mahasiswa baru mencakup 4 aspek: penjelasan umum PT, integritas akademik, bebas kekerasan, dan adaptasi kampus?\",\"bobot\":0},{\"id\":\"q2\",\"text\":\"Apakah terdapat layanan administrasi akademik yang memadai?\",\"bobot\":0},{\"id\":\"q3\",\"text\":\"Apakah terdapat layanan bimbingan konseling?\",\"bobot\":0},{\"id\":\"q4\",\"text\":\"Apakah terdapat layanan kesehatan?\",\"bobot\":0},{\"id\":\"q5\",\"text\":\"Apakah terdapat layanan keperluan dasar mahasiswa berkebutuhan khusus?\",\"bobot\":0},{\"id\":\"q6\",\"text\":\"Apakah dilakukan survey kepuasan atas layanan mahasiswa?\",\"bobot\":0}]'),('AK-24','Akuntabilitas','Tata Pamong – SOTK & Renstra Pendidikan','-','-','Semua','[{\"id\":\"q1\",\"text\":\"Apakah terdapat dokumen formal Struktur Organisasi dan Tata Kerja (SOTK) yang lengkap mencakup: penyusun kebijakan, pelaksana akademik, pengawas/penjaminan mutu, penunjang akademik, pelaksana administrasi?\",\"bobot\":0},{\"id\":\"q2\",\"text\":\"Apakah renstra pengembangan pendidikan UPPS tersedia dan mencakup Program Studi yang diakreditasi?\",\"bobot\":0},{\"id\":\"q3\",\"text\":\"Apakah SOTK dan renstra ditetapkan dengan ketetapan formal dan berjalan efektif?\",\"bobot\":0},{\"id\":\"q4\",\"text\":\"Apakah renstra mencakup peta pengembangan jangka panjang, menengah, dan pendek dengan indikator terukur?\",\"bobot\":0}]'),('AK-25','Akuntabilitas','Sistem Tata Pamong & Mitigasi Risiko','-','-','Semua','[{\"id\":\"q1\",\"text\":\"Apakah pengawasan dan pengendalian kegiatan pendidikan dilakukan dalam bidang akademik dan nonakademik?\",\"bobot\":0},{\"id\":\"q2\",\"text\":\"Apakah terdapat pemantauan dan evaluasi pelaksanaan kegiatan pendidikan serta efektivitas kebijakan akademik?\",\"bobot\":0},{\"id\":\"q3\",\"text\":\"Apakah pemantauan potensi risiko (korupsi, pengaduan, penurunan data PD Dikti) dilakukan?\",\"bobot\":0},{\"id\":\"q4\",\"text\":\"Apakah terdapat penjaminan kepatuhan pada otoritas akademik dan etika akademik?\",\"bobot\":0},{\"id\":\"q5\",\"text\":\"Apakah terdapat sistem penerimaan, pendokumentasian, dan penyelesaian keluhan/pengaduan?\",\"bobot\":0},{\"id\":\"q6\",\"text\":\"Apakah terdapat pelaporan dan akuntabilitas terhadap penggunaan bantuan pendanaan dari mitra?\",\"bobot\":0},{\"id\":\"q7\",\"text\":\"Apakah UPPS memenuhi ketentuan peraturan ketenagakerjaan (UU No.13/2003) dan ASN (UU No.20/2023)?\",\"bobot\":0}]'),('AK-26','Akuntabilitas','Sistem TIK Pengelolaan Data & Informasi','-','-','Semua','[{\"id\":\"q1\",\"text\":\"Apakah terdapat kebijakan formal terkait pengembangan sarana TIK untuk manajemen dan pengelolaan data?\",\"bobot\":0},{\"id\":\"q2\",\"text\":\"Apakah sistem TIK memastikan keamanan, kebenaran, akurasi, kelengkapan, dan kemutakhiran data akademik?\",\"bobot\":0},{\"id\":\"q3\",\"text\":\"Apakah sistem TIK mendukung perencanaan, pelaksanaan, pengawasan, dan pengambilan keputusan?\",\"bobot\":0},{\"id\":\"q4\",\"text\":\"Apakah data profil dan kinerja prodi dilaporkan ke PD Dikti sesuai ketentuan perundangan?\",\"bobot\":0},{\"id\":\"q5\",\"text\":\"Apakah data dan informasi prodi dapat diakses publik?\",\"bobot\":0},{\"id\":\"q6\",\"text\":\"Apakah terdapat rencana pengembangan TIK untuk mendukung kegiatan pendidikan?\",\"bobot\":0}]'),('AK-27','Akuntabilitas','Efektivitas Kepemimpinan UPPS & Prodi','-','-','Semua','[{\"id\":\"q1\",\"text\":\"Apakah terdapat bukti sahih kepemimpinan operasional yang menggerakkan seluruh sumber daya internal secara optimal?\",\"bobot\":0},{\"id\":\"q2\",\"text\":\"Apakah terdapat bukti kepemimpinan organisasional yang menggerakkan dan mengharmonisasikan suasana kerja kondusif?\",\"bobot\":0},{\"id\":\"q3\",\"text\":\"Apakah terdapat bukti kepemimpinan publik berupa kerjasama yang menjadikan prodi sebagai rujukan masyarakat?\",\"bobot\":0},{\"id\":\"q4\",\"text\":\"Apakah efektivitas kepemimpinan mencakup ketiga aspek tersebut secara konsisten?\",\"bobot\":0}]'),('AK-28','Akuntabilitas','Good University Governance (GUG)','-','-','Semua','[{\"id\":\"q1\",\"text\":\"Apakah terdapat dokumen formal GUG mencakup 6 aspek: kredibilitas, transparansi, akuntabilitas, tanggung jawab, berkeadilan, dan manajemen risiko?\",\"bobot\":0},{\"id\":\"q2\",\"text\":\"Apakah implementasi GUG berjalan konsisten di lingkungan UPPS?\",\"bobot\":0},{\"id\":\"q3\",\"text\":\"Apakah UPPS mengumumkan ringkasan laporan tahunan kepada masyarakat?\",\"bobot\":0},{\"id\":\"q4\",\"text\":\"Apakah terdapat lembaga/unit penegakan kode etik yang berfungsi efektif dengan pedoman formal?\",\"bobot\":0},{\"id\":\"q5\",\"text\":\"Apakah terdapat kebijakan dan bukti implementasi kampus bebas kekerasan seksual, perundungan, dan diskriminasi?\",\"bobot\":0},{\"id\":\"q6\",\"text\":\"Apakah ada penanganan dan penindakan kasus kekerasan seksual/perundungan/intoleransi di UPPS?\",\"bobot\":0}]'),('AK-29','Akuntabilitas','Pengelolaan Fungsional & Operasional UPPS','-','-','Semua','[{\"id\":\"q1\",\"text\":\"Apakah terdapat bukti formal keberfungsian perencanaan (planning) di UPPS?\",\"bobot\":0},{\"id\":\"q2\",\"text\":\"Apakah terdapat bukti formal keberfungsian pengorganisasian (organizing)?\",\"bobot\":0},{\"id\":\"q3\",\"text\":\"Apakah terdapat bukti formal keberfungsian penempatan personil (staffing)?\",\"bobot\":0},{\"id\":\"q4\",\"text\":\"Apakah terdapat bukti formal keberfungsian pengarahan (leading)?\",\"bobot\":0},{\"id\":\"q5\",\"text\":\"Apakah terdapat bukti formal keberfungsian pengawasan (controlling)?\",\"bobot\":0},{\"id\":\"q6\",\"text\":\"Apakah kelima aspek pengelolaan fungsional dan operasional berjalan konsisten?\",\"bobot\":0}]'),('AK-30','Akuntabilitas','Suasana Akademik Program Studi','-','-','S1','[{\"id\":\"q1\",\"text\":\"Apakah terdapat dokumen formal kebijakan suasana akademik: otonomi keilmuan, kebebasan akademik, dan kebebasan mimbar akademik?\",\"bobot\":0},{\"id\":\"q2\",\"text\":\"Apakah kegiatan tridharma menjunjung tinggi integritas dan etika akademik?\",\"bobot\":0},{\"id\":\"q3\",\"text\":\"Apakah suasana akademik yang kondusif terwujud secara konsisten setiap bulan?\",\"bobot\":0},{\"id\":\"q4\",\"text\":\"Apakah terdapat kegiatan seminar, diskusi ilmiah, kuliah tamu, dan kegiatan akademik kemahasiswaan secara rutin?\",\"bobot\":0}]'),('AK-31','Akuntabilitas','Kebijakan Penerimaan Mahasiswa Baru','-','-','Semua','[{\"id\":\"q1\",\"text\":\"Apakah terdapat kebijakan penerimaan mahasiswa baru yang afirmatif, inklusif, dan adil (tidak diskriminatif atas suku, ras, agama, disabilitas)?\",\"bobot\":0},{\"id\":\"q2\",\"text\":\"Apakah terdapat upaya perluasan akses melalui: a) Pembelajaran Jarak Jauh (PJJ)?\",\"bobot\":0},{\"id\":\"q3\",\"text\":\"Apakah terdapat sharing sumber daya pembelajaran antar institusi?\",\"bobot\":0},{\"id\":\"q4\",\"text\":\"Apakah terdapat skema beasiswa: afirmasi, 3T, mahasiswa berprestasi tidak mampu, minat/bakat?\",\"bobot\":0},{\"id\":\"q5\",\"text\":\"Apakah terdapat kebijakan rekrutmen melalui Rekognisi Pembelajaran Lampau (RPL)?\",\"bobot\":0}]'),('AK-32','Akuntabilitas','Sistem Layanan Mahasiswa','-','-','S1','[{\"id\":\"q1\",\"text\":\"Apakah terdapat program penyiapan mahasiswa baru mencakup 4 aspek: penjelasan umum PT, integritas akademik, bebas kekerasan, dan adaptasi kampus?\",\"bobot\":0},{\"id\":\"q2\",\"text\":\"Apakah terdapat layanan administrasi akademik yang memadai?\",\"bobot\":0},{\"id\":\"q3\",\"text\":\"Apakah terdapat layanan bimbingan konseling?\",\"bobot\":0},{\"id\":\"q4\",\"text\":\"Apakah terdapat layanan kesehatan?\",\"bobot\":0},{\"id\":\"q5\",\"text\":\"Apakah terdapat layanan keperluan dasar mahasiswa berkebutuhan khusus?\",\"bobot\":0},{\"id\":\"q6\",\"text\":\"Apakah terdapat layanan pemenuhan beban belajar di luar program studi? (MBKM: magang, pertukaran pelajar, wirausaha, dll.)\",\"bobot\":0},{\"id\":\"q7\",\"text\":\"Apakah dilakukan survey kepuasan atas layanan mahasiswa?\",\"bobot\":0}]'),('AK-33','Akuntabilitas','Implementasi Layanan Berintegritas','-','-','Semua','[{\"id\":\"q1\",\"text\":\"Apakah terdapat dokumen dan bukti sahih implementasi layanan yang berintegritas (bersih dan melayani)?\",\"bobot\":0},{\"id\":\"q2\",\"text\":\"Apakah layanan berintegritas dievaluasi secara periodik (triwulan)?\",\"bobot\":0},{\"id\":\"q3\",\"text\":\"Apakah terdapat prosedur formal layanan yang bersih dan profesional?\",\"bobot\":0}]'),('AK-34','Akuntabilitas','Kepuasan Pemangku Kepentingan (Tata Pamong)','-','-','Semua','[{\"id\":\"q1\",\"text\":\"Apakah survey kepuasan menggunakan instrumen yang sahih, andal, dan mudah digunakan?\",\"bobot\":0},{\"id\":\"q2\",\"text\":\"Apakah survey kepuasan dilaksanakan secara berkala and datanya terekam komprehensif?\",\"bobot\":0},{\"id\":\"q3\",\"text\":\"Apakah hasil survey dianalisis dengan metode yang tepat untuk pengambilan keputusan?\",\"bobot\":0},{\"id\":\"q4\",\"text\":\"Apakah umpan balik kepuasan ditindaklanjuti untuk perbaikan mutu secara berkala?\",\"bobot\":0},{\"id\":\"q5\",\"text\":\"Apakah survey mencakup semua stakeholder: mahasiswa, dosen, tendik, mitra, lulusan, pengguna lulusan?\",\"bobot\":0}]'),('AK-35','Akuntabilitas','Zona Layanan Berintegritas (WBK/WBBM)','-','-','Semua','[{\"id\":\"q1\",\"text\":\"Apakah terdapat dokumen peraturan layanan berintegritas di unit kerja?\",\"bobot\":0},{\"id\":\"q2\",\"text\":\"Apakah implementasi zona layanan berintegritas berjalan konsisten and terevaluasi?\",\"bobot\":0},{\"id\":\"q3\",\"text\":\"Apakah terdapat survey kepuasan stakeholder terkait layanan berintegritas?\",\"bobot\":0},{\"id\":\"q4\",\"text\":\"Apakah terdapat kick-off meeting komitmen WBK dan/atau WBBM?\",\"bobot\":0}]'),('BM-001','Budaya Mutu','SPMI - Standar & Tata Kelola','-','-','S3','[{\"id\":\"q1\",\"text\":\"Apakah Program Studi memiliki Standar Pendidikan Tinggi yang melampaui SN Dikti dan berorientasi akademik serta pengembangan ilmu pengetahuan ba