CREATE TABLE `MonevRecord` (
  `id` varchar(191) NOT NULL,
  `prodiId` varchar(191) NOT NULL,
  `instrumentId` varchar(191) NOT NULL,
  `tahun_akademik` varchar(191) NOT NULL,
  `semester` varchar(191) NOT NULL,
  `analisa_kpma` text DEFAULT NULL,
  `tindak_lanjut_kpma` text DEFAULT NULL,
  `answers` text NOT NULL,
  `updatedAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `MonevRecord_prodiId_instrumentId_tahun_akademik_semester_key` (`prodiId`,`instrumentId`,`tahun_akademik`,`semester`),
  KEY `MonevRecord_instrumentId_fkey` (`instrumentId`),
  CONSTRAINT `MonevRecord_instrumentId_fkey` FOREIGN KEY (`instrumentId`) REFERENCES `Instrument` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `MonevRecord_prodiId_fkey` FOREIGN KEY (`prodiId`) REFERENCES `Prodi` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
