INSERT INTO `MonevRecord` VALUES ('cmok5ytxg0001ot9gt7qst7ah','cmoj7qv6j000eot5o8oiezdnp','BM-1','2025/2026','Ganjil','','','{\"q1\":{\"pilihan\":\"Ya\",\"buktiLinks\":[\"https://drive.google.com/file/d/1yTapGzifCFWZGM6Z34HDmLgkRIEYYhUX/view?usp=drivesdk\",\"https://drive.google.com/file/d/11Aw0wkLARBaS3GZ86shQTrrYPm-T9-zG/view?usp=drivesdk\",\"https://drive.google.com/file/d/18Uj-FD9z9cwWXrgrjrujkGPZHQcegM4X/view?usp=drivesdk\",\"https://docs.google.com/spreadsheets/d/1xMnuyfYdWv4mJ5saGElQ6m11WVkhulhf/edit?usp=drivesdk&ouid=116037963784605049050&rtpof=true&sd=true\"],\"evaluasiDiri\":\"1. Dokumen Standar SPMI FAI.\\n\\n2. SK Hafalan Juz 30, contoh penilaian, sertifikat dan pedoman.\\n\\n3. SK Kegiatan Habituasi BKPI.\\n\\n4. Lembar Monitoring Habituasi.\",\"catatanAuditor\":\"1. Ada dokumen standar namun masih menggunakan standar dari peraturan lama terkait SPMI.\\n\\n2. Bukti lengkap untuk kewajiban hafalan juz 30.\\n\\n3. SK kegiatan Habituasi ada.\\n\\n4. Lembar monitoring habituasi tahun 2023, seharusnya lebih baru misal 2025\",\"kesesuaianBukti\":\"Ya\"},\"q2\":{\"pilihan\":\"Ya\",\"buktiLinks\":[\"https://drive.google.com/file/d/1mD2DPVZT477cjPuoGTVvhrg9yEUWDu_W/view?usp=drivesdk\"],\"evaluasiDiri\":\"1. Panduan Implementasi Kurikulum Merdeka Belajar & Kampus Merdeka Program Studi\",\"catatanAuditor\":\"1. Ada pedoman penyusunan kurikulum namun belum terdapat pedoman OBE yang ditail di dalamnya. Informasi dari BP2SI pedoman selesai Juni 2026.\",\"kesesuaianBukti\":\"Ya\"},\"q7\":{\"pilihan\":\"Ya\",\"evaluasiDiri\":\"1. Laporan AMI 2023-2025.\\n\\n2. Laporan RTM 2023-2025.\\n\\n3. Laporan RTL 2023-2025.\",\"buktiLinks\":[\"https://drive.google.com/file/d/1cKHCuzEB_Lc2vEPBE4gqjieQtYpwJKlB/view?usp=drivesdk\",\"https://drive.google.com/file/d/1hzl0ZEtvK8M9vxWtxZgcyDJYbWii65_R/view?usp=drivesdk\",\"https://drive.google.com/file/d/1J_sURXer7ItN_EZpfMK52Kc73mmxbQAP/view?usp=drivesdk\"],\"catatanAuditor\":\"Laporan AMI, RTM, RTL lengkap tahun 2023,2024,2025\",\"kesesuaianBukti\":\"Ya\"},\"q3\":{\"pilihan\":\"Ya\",\"evaluasiDiri\":\"1. Laporan AMI 2023-2025\\n\\n2. Laporan RTM 2023-2025.\\n\\n3. Laporan RTL 2023-2025\",\"buktiLinks\":[\"https://drive.google.com/file/d/1k6_Bde5MAekDWSC_YhAxUwII5BsSmoKn/view?usp=drivesdk\",\"https://drive.google.com/file/d/13HyE8z84S7fuoWVOOouJMhs2pN9F5Jty/view?usp=drivesdk\",\"https://drive.google.com/file/d/1hjRyX4yn5ZzEL0rFl2coMozOiD3AK6wM/view?usp=drivesdk\"],\"catatanAuditor\":\"Laporan AMI, RTM, RTL lengkap tahun 2023,2024,2025\",\"kesesuaianBukti\":\"Ya\"},\"q4\":{\"pilihan\":\"Ya\",\"evaluasiDiri\":\"1. Statuta 2024 sudah mencantumkan GPM dan GKM\\n\\n2. SK GPM sebagai penjamin mutu tingkat Fakultas\\n\\n3. SK GKM sebagai penjamin mutu tingkat prodi.\",\"buktiLinks\":[\"https://drive.google.com/file/d/1xEDd9jb3SgaX_zdOctt4uVPLLMGBTirA/view?usp=drivesdk\",\"https://drive.google.com/file/d/15JUt9jaS4srhQUAxQHDyO1Wmos0aMfxU/view?usp=drivesdk\",\"https://drive.google.com/file/d/1e0PRQpgexeFNbZi3VnFc6rL3k7cu-8Re/view?usp=drivesdk\"],\"catatanAuditor\":\"Fungsi penjaminan mutu sudah tercantum di statuta\",\"kesesuaianBukti\":\"Ya\"},\"q5\":{\"pilihan\":\"Ya\",\"evaluasiDiri\":\"1. Laporan AMI 2023-2025.\\n\\n2. Laporan RTM 2023-2025.\\n\\n3. Laporan RTL 2023-2025.\",\"buktiLinks\":[\"https://drive.google.com/file/d/1x1nBS356xSd6gDR7xnibwqvZ8TrlDbPb/view?usp=drivesdk\",\"https://drive.google.com/file/d/1EGFD4GIEfS_NM9daBtvhJs3li6LZCRr2/view?usp=drivesdk\",\"https://drive.google.com/file/d/1R5I5vg9M5p4P8mSneDlS3a2YQxGthLz6/view?usp=drivesdk\"],\"catatanAuditor\":\"Laporan AMI, RTM, RTL lengkap tahun 2023,2024,2025\",\"kesesuaianBukti\":\"Ya\"},\"q6\":{\"pilihan\":\"Ya\",\"evaluasiDiri\":\"1. Laporan AMI 2023-2025.\\n\\n2. Laporan RTM 2023-2025.\\n\\n3. Laporan RTL 2023-2025.\",\"buktiLinks\":[\"https://drive.google.com/file/d/1K5VzQKnrWnxZ1C3y6GKyWHNMH0Vl1iUK/view?usp=drivesdk\",\"https://drive.google.com/file/d/1HS4VmZvJI02HHUfqWt9NSs2-xHXtDsDk/view?usp=drivesdk\",\"https://drive.google.com/fil